const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
async function load(path){const r=await fetch(path);if(!r.ok)throw Error('Retained report unavailable');return r.json();}
try{const r=await load('assets/tracking/external-video-results.json'),root=document.getElementById('external-results');root.replaceChildren();for(const c of r.clips){const p=el('p',`${c.kind}: ${c.frames} frames tested; ${c.raw_marker_matches} raw color matches; ${c.published_player_identities} verified identities published. These counts are not detection accuracy.`);root.append(p);}}catch(e){document.getElementById('external-results').textContent=e.message;}
try{const r=await load('assets/tracking/heldout-commentary-summary.json'),root=document.getElementById('comparison-results');root.replaceChildren(el('p',`${r.cases} paired cases. ${r.complete?'Run complete.':'Run incomplete; failures retained.'}`));for(const [arm,v]of Object.entries(r.arms))root.append(el('p',`${arm==='crew'?'Three-call crew':'Single-call editor'}: ${v.calls} requests, ${v.tokens} tokens, ${v.compliant}/${v.outputs} role outputs passed wording/citation checks.`));const compared=Math.min(r.arms?.crew?.outputs||0,r.arms?.baseline?.outputs||0);root.append(el('p',`${r.identical_role_texts}/${compared} role contributions used identical wording in both arms. This run does not establish a quality advantage for extra calls.`));root.append(el('p','The retained run compares an earlier three-call crew with a single-call editor. The current four-model handoff still requires fresh independent blind ratings; no winner is declared.'));}catch(e){document.getElementById('comparison-results').textContent=e.message;}
